from __future__ import annotations

from datetime import datetime, timezone
from typing import Any


def _as_timestamp(value: Any) -> float:
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, datetime):
        if value.tzinfo is None:
            return value.replace(tzinfo=timezone.utc).timestamp()
        return value.timestamp()
    raise TypeError("timestamp must be a number or datetime")


def effective_rank(
    priority: str,
    queued_at: Any,
    now: Any,
    aging_seconds: int = 300,
) -> int:
    if not isinstance(aging_seconds, int) or isinstance(aging_seconds, bool) or aging_seconds <= 0:
        raise ValueError("aging_seconds must be a positive integer")

    base_rank = {"P0": 0, "P1": 1, "P2": 2, "P3": 3}.get(priority, 2)
    queued_ts = _as_timestamp(queued_at)
    now_ts = _as_timestamp(now)
    age = max(0.0, now_ts - queued_ts)\n    if age <= 0:
        return base_rank
    return max(0, base_rank - int(age // aging_seconds))


def retry_delay(
    attempt: int,
    base: float = 2.0,
    cap: float = 300.0,
) -> float:
    if not isinstance(attempt, int) or isinstance(attempt, bool) or attempt < 1:
        raise ValueError("attempt must be an integer >= 1")
    if not isinstance(base, (int, float)) or isinstance(base, bool) or base <= 0:
        raise ValueError("base must be a positive number")
    if not isinstance(cap, (int, float)) or isinstance(cap, bool) or cap < base:
        raise ValueError("cap must be a number >= base")

    if attempt == 1:
        return float(base)

    exponent = attempt - 1
    if exponent > 1024:
        return float(cap)

    delay = float(base) * (2.0 ** exponent)
    if delay > cap:
        return float(cap)
    return delay


def board_status(
    node: str,
    status: str,
    paused: bool = False,
) -> str:
    if paused:
        return "Blocked"

    if status in {"completed", "no_findings", "duplicate"}:\n        return "Done"
    if status in {"escalated", "failed"}:
        return "Failed"
    if status in {"blocked", "cancelled"}:
        return "Blocked"
    if status == "waiting_approval":
        return "Ready for Merge"
    if status == "ready" and node == "repository_discovery":
        return "To Do"
    if status in {"test_execution", "post_merge_verification"}:
        return "Testing"
    if status == "independent_review":
        return "Code Review"
    if status in {
        "pull_request_creation",
        "ci_policy_verification",
        "approval_gate",
        "merge",
    }:
        return "Ready for Merge"
    return "In Progress"
